export function words(text){
 const output=[];let index=0;
 const space=c=>c===' '||c==='\t'||c==='\r'||c==='\n';
 const escape=()=>{index++;if(index>=text.length)throw new SyntaxError('escape');return text[index++];};
 while(index<text.length){
  while(index<text.length&&space(text[index]))index++;
  if(index===text.length)break;
  let word='';
  while(index<text.length&&!space(text[index])){
   const c=text[index];
   if(c==='\\'){word+=escape();continue;}
   if(c==="'"||c==='"'){
    const delimiter=c;index++;
    while(index<text.length&&text[index]!==delimiter){if(delimiter==='"'&&text[index]==='\\')word+=escape();else word+=text[index++];}
    if(index===text.length)throw new SyntaxError('quote');index++;continue;
   }
   word+=text[index++];
  }
  output.push(word);
 }
 return output;
}

